import{C as a,T as i,B as n,M as r}from"./truck-f4611f6d.js";import{B as o}from"./briefcase-86e8bf25.js";import{H as s}from"./heart-f4682e05.js";import{H as l,G as c}from"./index-fb6640b7.js";const d=[{id:"it-tech",slug:"it-technology",icon:a,title:"IT & Technology",shortDesc:"Tax incentives, PSEB, export documentation, and cross-border invoicing for IT companies and freelancers.",desc:"Pakistan's IT sector enjoys significant tax incentives — but navigating PSEB registration, export remittance rules, and FBR compliance can be complex. We specialise in maximising your tax benefits while keeping you fully compliant.",heroImage:"https://images.unsplash.com/photo-1488590528505-98d2b5aba04b?auto=format&fit=crop&w=1200&q=70",challenges:["Claiming IT export income tax exemption correctly","Managing cross-border invoicing and foreign remittance","PSEB registration and annual renewal complexities","Distinguishing local vs exported services for PST purposes","Freelancer income declaration and ATL status maintenance"],solutions:["PSEB registration enabling 0.25% reduced tax on IT exports","Foreign remittance tax advisory and banking documentation","End-to-end PSEB registration and renewal support","Provincial sales tax classification for IT services","Complete NTN, ATL, and return filing for freelancers"],services:[{title:"PSEB Registration",desc:"Get registered with Pakistan Software Export Board for tax exemptions and incentives."},{title:"Freelancer NTN & Tax Filing",desc:"NTN registration, Iris profile, and annual income tax return for Fiverr/Upwork/Amazon earners."},{title:"IT Company Setup",desc:"SECP registration, NTN, PSEB, and PRA/SRB registration for IT companies."},{title:"Software Export Registration",desc:"Registration and compliance guidance for software and IT service exporters."},{title:"FBR Notices & ATL Compliance",desc:"Handle FBR notices, maintain ATL status, and manage audit proceedings."}],taxTreatments:["IT export services are taxed at 0% (effective exemption) if payment received in foreign currency","PSEB-registered individuals pay 0.25% flat tax on gross IT export receipts","Local IT services are subject to provincial sales tax (PRA 16%, SRB 13%, KPRA 15%)","Withholding tax deducted by clients under Section 153(1)(b) is adjustable against annual liability"],faqs:[{q:"Do IT freelancers need to pay income tax in Pakistan?",a:"Yes, but at a significantly reduced rate. PSEB-registered IT exporters pay just 0.25% on gross foreign receipts. Without PSEB registration, income tax slabs apply to net income."},{q:"Is Fiverr/Upwork income taxable in Pakistan?",a:"Yes. Foreign platform income must be declared in your annual return. If received in foreign currency through banking channels, it qualifies for reduced IT export tax treatment."},{q:"Does my IT company need to register for PRA sales tax?",a:"If your services are exported, they are generally zero-rated. For local IT services in Punjab, PRA registration is required once your turnover exceeds the threshold."}],relevantServices:[{title:"PSEB Registration",path:"/services/pseb-registration"},{title:"Freelancer Tax Filing",path:"/services/freelancer-tax-filing"},{title:"IT Company Setup",path:"/services/it-company-setup"},{title:"Software Export Registration",path:"/services/software-export-registration"}]},{id:"manufacturing",slug:"manufacturing",icon:i,title:"Manufacturing & Industrial",shortDesc:"GST/PST registrations, sales tax advisory, and machinery documentation for manufacturers.",desc:"Manufacturing businesses face some of the most complex tax obligations in Pakistan — from input/output GST reconciliation to withholding tax on raw material purchases. Our sector experts manage the entire compliance lifecycle.",heroImage:"https://images.unsplash.com/photo-1581091226825-a6a2a5aee158?auto=format&fit=crop&w=1200&q=70",challenges:["Complex input tax and output tax reconciliation","Documentation for machinery and capital allowance claims","Large-volume sales invoicing and monthly GST returns","Withholding tax compliance on raw material purchases","Managing STRO (Sales Tax Refund Orders) for exporters"],solutions:["Complete GST registration, reconciliation, and monthly filing","Capital allowance calculations and asset documentation","Structured invoicing templates and monthly reporting service","Withholding tax compliance and certificate management","STRO processing and export refund documentation"],services:[{title:"Sales Tax Registration & Monthly Filing",desc:"FBR GST registration, monthly return preparation, and compliance."},{title:"Input/Output Tax Reconciliation",desc:"Reconciliation of purchases and sales for accurate tax liability calculation."},{title:"Withholding Tax Compliance",desc:"WHT on raw materials, supplies, and services — certificates and returns."},{title:"Corporate Income Tax",desc:"Annual company tax return and advance tax management."},{title:"FBR Audit Representation",desc:"Professional representation during FBR audits and notice proceedings."}],taxTreatments:["GST at 18% on most goods under the Sales Tax Act, 1990","Input tax credit available on purchases used in manufacturing","WHT at 4% on supply of goods under Section 153(1)(a) — adjustable","Exporters can claim input tax refund for goods exported","Capital assets qualify for initial allowance and depreciation deductions"],faqs:[{q:"Can manufacturers claim input tax credit?",a:"Yes. Registered manufacturers can claim credit for GST paid on raw materials, packaging, and machinery used in production, offsetting their output tax liability."},{q:"What is the WHT rate on manufacturing contracts?",a:"Supply of goods attracts WHT at 4% for filers and 8% for non-filers under Section 153. This is adjustable against the annual income tax return."},{q:"How often do manufacturers file GST returns?",a:"Monthly — by the 18th of the following month. Large taxpayers (annual turnover > Rs. 250 million) file by the 10th."}],relevantServices:[{title:"Sales Tax Registration",path:"/services/sales-tax-registration-monthly-filing"},{title:"FBR Audit Representation",path:"/services/fbr-audit-representation"},{title:"Business NTN Registration",path:"/services/business-ntn-registration"},{title:"Tax Planning & Advisory",path:"/services/tax-planning-advisory"}]},{id:"retail-ecommerce",slug:"retail-ecommerce",icon:n,title:"Retail & E-commerce",shortDesc:"Sales tax, online marketplace invoicing, and provincial PST for retailers and online stores.",desc:"E-commerce in Pakistan is booming — but so are the compliance requirements. From Daraz seller accounts to Shopify stores, we handle your sales tax, NTN, and marketplace invoicing obligations so you can focus on growing sales.",heroImage:"https://images.unsplash.com/photo-1556742049-0cfed4f6a45d?auto=format&fit=crop&w=1200&q=70",challenges:["Marketplace seller invoicing and reverse charge rules","Managing multiple provincial PST requirements","Reconciling high-volume micro-transactions","Import duty and customs classification for goods","NTN requirement for Daraz, Shopify, Amazon Pakistan sellers"],solutions:["Marketplace invoice mapping and correct tax treatment","Provincial PST registration (PRA, SRB, KPRA, BRA)","Automation-ready reporting templates for reconciliation","Import/export NTN setup and customs advisory","NTN registration and e-commerce setup compliance"],services:[{title:"NTN Registration",desc:"Personal or business NTN for online sellers and retail entrepreneurs."},{title:"Sales Tax Registration (STRN)",desc:"FBR GST registration and monthly return filing for retailers."},{title:"E-commerce Setup Compliance",desc:"Complete NTN, STRN, and documentation for Daraz, Shopify, Amazon sellers."},{title:"Import/Export NTN",desc:"Add import/export activity to your FBR profile for trading businesses."},{title:"Provincial PST Registration",desc:"PRA/SRB registration for retail service providers in Punjab and Sindh."}],taxTreatments:["Retailers with turnover > Rs. 100 million must register for GST","Tier-1 retailers (large stores, franchises) pay GST at 18%","Daraz and marketplace commissions attract WHT under Section 233","Import of goods attracts customs duty, regulatory duty, and additional sales tax","Provincial sales tax (PRA) applies on services provided in Punjab"],faqs:[{q:"Do I need an NTN to sell on Daraz?",a:"Yes. Daraz requires sellers to provide a valid NTN for tax compliance. Without it, Daraz may deduct WHT at higher non-filer rates from your payments."},{q:"Do online retailers need to register for GST?",a:"Retailers with annual taxable turnover above Rs. 100 million must register. Smaller retailers may not be required, but voluntary registration can be beneficial for claiming input tax."},{q:"How is Amazon FBA income taxed in Pakistan?",a:"Income from Amazon is treated as export of goods/services. It must be declared in your annual tax return. If received in foreign currency through banking channels, it may qualify for reduced tax treatment."}],relevantServices:[{title:"NTN Registration",path:"/services/ntn-registration-modification"},{title:"Sales Tax Registration",path:"/services/sales-tax-registration-monthly-filing"},{title:"E-Commerce Setup",path:"/services/e-commerce-setup"},{title:"Import Export NTN",path:"/services/import-export-ntn"}]},{id:"professional-services",slug:"professional-services",icon:o,title:"Professional Services",shortDesc:"Simplified compliance for consultants, law firms, accountants, and agencies.",desc:"Professionals and consultancy firms face a unique compliance landscape — irregular billing, professional service tax, and cross-border client invoicing. We offer lean compliance packages tailored for consultants and firms of all sizes.",heroImage:"https://images.unsplash.com/photo-1454165804606-c3d57bc86b40?auto=format&fit=crop&w=1200&q=70",challenges:["Irregular billing and contract-based income management","Professional service tax (PST) in multiple provinces","WHT deduction by clients under Section 153","Cross-border client invoicing for international consultants","AOP vs Company structure decision for partnerships"],solutions:["Retainer-friendly annual tax filing processes","PRA/SRB registration and monthly return management","WHT certificate management and annual adjustment","International invoice guidance and tax treaty positioning","AOP and partnership registration advisory"],services:[{title:"NTN Registration & ATL Maintenance",desc:"Personal or business NTN, ATL activation, and ongoing compliance."},{title:"Annual Income Tax Return",desc:"Comprehensive return filing including professional income and deductions."},{title:"PRA/SRB Registration",desc:"Provincial sales tax registration for professional service providers."},{title:"Partnership / AOP Registration",desc:"Registration of consulting partnerships and AOPs with the Registrar."},{title:"Business Advisory & Tax Planning",desc:"Structuring advice to minimise tax liability within professional firms."}],taxTreatments:["WHT at 8% (filer) or 15% (non-filer) on professional fee receipts under Section 153(1)(b)","Provincial sales tax on professional services: PRA 16%, SRB 13%, KPRA 15%","AOP income taxed at individual slab rates, with further distribution tax on partners","Professional expenses (office rent, utilities, salaries) are deductible against income","Partners in an AOP can deduct WHT paid at the AOP level against their personal tax"],faqs:[{q:"Do consultants need to register for provincial sales tax?",a:"Professional consultants providing services in Punjab must register with PRA (16% tax). Sindh-based consultants register with SRB (13%). This applies once your annual taxable service revenue exceeds the threshold."},{q:"How is WHT on professional fees handled?",a:"When a client pays you a professional fee, they deduct WHT at 8% (for filers). You receive a WHT certificate. This deducted amount is adjustable against your annual income tax liability."},{q:"Should my consultancy be an AOP or a company?",a:"An AOP is simpler and more flexible for small partnerships. A Private Limited Company offers limited liability, better credibility, and is more suitable for larger firms or those seeking investment. We advise based on your specific situation."}],relevantServices:[{title:"NTN Registration",path:"/services/ntn-registration-modification"},{title:"PRA Registration",path:"/services/pra-registration"},{title:"Partnership Registration",path:"/services/partnership-registration"},{title:"Business Advisory",path:"/services/business-advisory"}]},{id:"healthcare",slug:"healthcare",icon:s,title:"Healthcare & Clinics",shortDesc:"Licensing, payroll, tax exemptions, and professional compliance for clinics and hospitals.",desc:"Healthcare providers in Pakistan navigate a complex intersection of professional regulation, payroll management for medical staff, and potential tax exemptions. Our team ensures full compliance while leveraging all available exemptions for your facility.",heroImage:"https://images.unsplash.com/photo-1576091160399-112ba8d25d1d?auto=format&fit=crop&w=1200&q=70",challenges:["Managing payroll for medical staff and visiting consultants","Navigating GST exemptions for healthcare services","Regulatory licensing alignment with FBR tax filings","WHT on consultant doctor payments under Section 153","Donor-funded project tax compliance"],solutions:["Payroll structuring, WHT deduction, and monthly returns","GST exemption eligibility review and certification","Integrated licensing and tax compliance calendar","Consultant payment documentation and WHT certificates","NGO/trust registration and donor fund compliance"],services:[{title:"Payroll Tax Management",desc:"Monthly salary WHT calculation, deduction, and deposit for clinic staff."},{title:"NTN & Tax Return Filing",desc:"Annual income tax return for clinic owners, doctors, and hospitals."},{title:"GST Exemption Documentation",desc:"Review and documentation of applicable healthcare GST exemptions."},{title:"WHT on Consultant Payments",desc:"Management of withholding tax on payments to visiting specialists."},{title:"NGO / Trust Registration",desc:"Registration for charitable hospitals and non-profit health organisations."}],taxTreatments:["Most healthcare services are exempt from GST under the Sixth Schedule of the Sales Tax Act","Medical equipment imports may attract reduced or zero customs duty","Consultant doctor payments attract 8% WHT under Section 153(1)(b)","Hospital/clinic income is taxed under normal income tax slabs or corporate rates","Charitable hospitals can apply for income tax exemption under Section 2(36)"],faqs:[{q:"Are hospital services subject to GST in Pakistan?",a:"Generally no. Medical and healthcare services are exempt from Federal GST. However, diagnostic laboratories and some commercial services may be subject to provincial sales tax depending on the nature of the service and province."},{q:"How is a visiting consultant doctor taxed?",a:"Consultant doctors are treated as professional service providers. The clinic must deduct WHT at 8% (filer) on each payment and issue a WHT certificate. The doctor includes this in their annual return."},{q:"Can a non-profit hospital get tax exemption?",a:"Yes. Hospitals operating as trusts or societies serving the public can apply for income tax exemption under Section 2(36). Specific conditions apply, and we guide you through the full application process."}],relevantServices:[{title:"NTN Registration",path:"/services/ntn-registration-modification"},{title:"NGO Registration",path:"/services/ngo-registration"},{title:"Income Tax Return Filing",path:"/services/income-tax-return-filing"},{title:"Business Advisory",path:"/services/business-advisory"}]},{id:"real-estate",slug:"real-estate",icon:l,title:"Real Estate & Construction",shortDesc:"Property tax advisory, builder/developer taxes, and compliance for landlords and developers.",desc:"Real estate in Pakistan is among the most heavily taxed and regulated sectors. From capital gains on property sales to fixed builder/developer taxes and rental income declarations, our specialists ensure you pay exactly what you owe — and not a rupee more.",heroImage:"https://images.unsplash.com/photo-1560518883-ce09059eeffa?auto=format&fit=crop&w=1200&q=70",challenges:["Capital gains tax on property sales and holding period calculations","Property transfer taxes: stamp duty, CVT, WHT under 236C/236K","Tax treatment of rental income vs development income","Fixed builder/developer tax under Sections 7C and 7D","Wealth statement reconciliation with property assets"],solutions:["CGT calculation based on holding period and FBR/DC valuation","Property transfer documentation and tax payment guidance","Structured rental vs development income tax planning","Builder/developer fixed tax computation and return filing","Wealth statement preparation including all property assets"],services:[{title:"Capital Gain Tax (Property)",desc:"CGT calculation and filing for property sales based on FBR 2025-26 rates."},{title:"Property Tax Advisory",desc:"Full advisory on stamp duty, CVT, WHT, and transfer taxes."},{title:"Builder Tax Calculator & Filing",desc:"Fixed tax computation and return filing under Sections 7C/7D."},{title:"Rental Income Filing",desc:"Declaration of rental income with allowable deductions under Section 15."},{title:"Wealth Statement",desc:"Comprehensive wealth statement including all immovable and movable assets."}],taxTreatments:["Capital gains on property: 15% for plots, 15% for constructed property (varies by holding period)","WHT under Section 236C: 3% (filer) on property sale value — deducted by buyer","WHT under Section 236K: 3% (filer), 12% (non-filer) on property purchase","Rental income taxed under Section 15; 20% standard deduction allowed","Builder fixed tax under Section 7C; Developer fixed tax under Section 7D per sq ft/sq yd"],faqs:[{q:"What is Capital Gains Tax on property in Pakistan?",a:"CGT applies to profit from selling property. The rate depends on the holding period. For plots and constructed properties held for less than 1 year, the full gain is taxed at applicable income tax slabs. The rate reduces as the holding period increases, reaching 0% after 4-6 years for most property types."},{q:"What is the difference between Section 236C and 236K?",a:"Section 236C applies to the seller — the buyer must deduct 3% (filer) WHT from the sale consideration. Section 236K applies to the buyer — they must pay 3% (filer) or 12% (non-filer) WHT when purchasing property. Both are adjustable advance taxes."},{q:"How are builder/developer taxes calculated?",a:"Fixed tax applies per square foot or square yard depending on the city and property type under Sections 7C (builders) and 7D (developers). Our tax calculator helps you estimate liability before project commencement."}],relevantServices:[{title:"Property Capital Gain Tax",path:"/services/property-capital-gain-tax"},{title:"Property Tax Advisory",path:"/services/property-tax-advisory"},{title:"Builder Tax Calculator",path:"/pakistan-tax-calculators?calc=builder"},{title:"Wealth Statement",path:"/services/wealth-statement-asset-reconciliation"}]},{id:"exports",slug:"exporters-trading",icon:c,title:"Exporters & Trading",shortDesc:"Documentation for export refunds, SEZ advisory, and foreign remittance tax guidance.",desc:"Exporters and trading companies benefit from zero-rated GST and export incentives — but accessing these benefits requires meticulous documentation. We ensure your export refunds are processed correctly and your compliance is airtight.",heroImage:"https://images.unsplash.com/photo-1494412574643-ff11b0a5c1c3?auto=format&fit=crop&w=1200&q=70",challenges:["Export refund / drawback documentation and processing","SEZ vs regular export tax positioning","Foreign currency repatriation and banking requirements","WHT on imports under Section 148","Income tax on trading profits and withholding reconciliation"],solutions:["End-to-end export refund preparation and FBR submission","SEZ advisory and tax optimisation strategy","Banking-ready remittance documentation support","Import WHT management and certificate tracking","Trading income return filing and WHT reconciliation"],services:[{title:"Export NTN & Registration",desc:"Add export activity to your FBR profile and PSW registration."},{title:"Sales Tax Refund Processing",desc:"Export refund claim preparation and follow-up with FBR."},{title:"PSW Registration",desc:"Pakistan Single Window registration for importers and exporters."},{title:"Import Export License",desc:"Obtaining Ministry of Commerce import/export license."},{title:"FBR Audit Assistance",desc:"Representing exporters in FBR audits and reconciliation proceedings."}],taxTreatments:["Exports of goods are zero-rated (0% GST) under the Sales Tax Act, allowing input tax refund","WHT at 6% under Section 148 applies on the value of imports — adjustable against annual liability","SEZ operators and SEZ enterprises enjoy income tax exemptions for varying periods","Trading income (purchase price minus selling price) is taxable under normal income tax slabs","Export proceeds must be repatriated within 4 months to maintain zero-rating eligibility"],faqs:[{q:"How do exporters claim GST refunds?",a:"Registered exporters can file refund claims with FBR for input tax paid on exported goods. The process involves submission of export documents, purchase invoices, and bank remittance proof. Tax Zilla manages the entire refund process on your behalf."},{q:"What is Pakistan Single Window (PSW)?",a:"PSW is Pakistan's integrated system for import and export processing. Registration is required for customs clearance. We handle PSW registration and ensure all your export/import documentation meets the requirements."},{q:"What is the WHT rate on imports?",a:"Section 148 WHT on imports is 6% of the import value for commercial importers. This is advance income tax adjustable against your annual return. Reduced rates apply under certain conditions."}],relevantServices:[{title:"Import Export NTN",path:"/services/import-export-ntn"},{title:"PSW Registration",path:"/services/psw-registration"},{title:"Import Export License",path:"/services/import-export-license"},{title:"FBR Audit Representation",path:"/services/fbr-audit-representation"}]},{id:"startups",slug:"startups-smes",icon:r,title:"Startups & SMEs",shortDesc:"Lean compliance packages, tax planning, and US/UAE company formation for growing startups.",desc:"Startups and SMEs need to get compliance right from day one — without it consuming resources better spent on growth. We offer startup-friendly packages covering entity setup, tax registration, and ongoing compliance that scale with your business.",heroImage:"https://images.unsplash.com/photo-1553877522-43269d4ea984?auto=format&fit=crop&w=1200&q=70",challenges:["Choosing the optimal entity structure from day one","Early-stage payroll, EOBI, and employee tax setup","Managing investor-related compliance (share issuance, valuations)","Maintaining ATL status and avoiding non-filer penalties","Cross-border expansion (US LLC, UAE setup) from Pakistan"],solutions:["Entity selection advisory (Sole Prop, AOP, Pvt Ltd) with tax impact analysis","Payroll setup with EOBI, WHT, and salary structuring","SECP compliance for share issuance and statutory filings","Annual return filing and ATL maintenance","US LLC registration, EIN, and UAE business setup support"],services:[{title:"SECP Company Registration",desc:"Incorporate your startup as a Private Limited or SMC company with SECP."},{title:"Business NTN Registration",desc:"Get your company and directors registered with FBR on day one."},{title:"Payroll & EOBI Setup",desc:"Structure employee salaries, register with EOBI, and manage monthly WHT."},{title:"USA LLC Registration",desc:"Form a US LLC, obtain EIN, and set up payment gateways (Stripe, PayPal)."},{title:"Annual Returns & Corporate Compliance",desc:"SECP annual filings, audited accounts, and FBR return compliance."}],taxTreatments:["Private Limited Companies taxed at 29% corporate income tax rate (FY 2025-26)","Small companies (turnover < Rs. 250 million) may qualify for reduced 20% tax rate","Startups can structure salaries to optimise personal income tax for founders","SECP and FBR both require annual filings — non-compliance leads to strike-off and penalties","US LLCs (single-member) are pass-through entities — income declared in Pakistan return"],faqs:[{q:"Should I register as Sole Proprietor or Pvt Ltd?",a:"A Sole Proprietorship is simpler and cheaper but carries unlimited personal liability. A Private Limited Company provides limited liability, better credibility, and is required for raising investment. Most growing startups eventually incorporate as Pvt Ltd. We advise on the best structure for your stage."},{q:"How soon should a startup register for NTN and GST?",a:"NTN registration should be done immediately — it is required for bank accounts, contracts, and property purchases. GST registration is required once your annual taxable turnover exceeds the FBR threshold (or if you wish to claim input tax credit)."},{q:"Can I form a US LLC from Pakistan?",a:"Yes. Many Pakistani entrepreneurs form US LLCs (in Wyoming, Delaware, or similar states) to access Stripe, PayPal, and US clients. Tax Zilla handles the full process including LLC formation, EIN application, and Pakistani tax declaration."}],relevantServices:[{title:"SECP Company Registration",path:"/services/secp-company-registration"},{title:"Business NTN Registration",path:"/services/business-ntn-registration"},{title:"USA LLC Registration",path:"/services/usa-llc-registration"},{title:"Annual Returns",path:"/services/annual-returns"}]}],f=e=>d.find(t=>t.slug===e);export{f as g,d as i};
